using System;
using System.Collections.Immutable;
using System.IO;
using System.Linq;
using Extensions.Pack;
using AspNetCore.MinimalApi.Sdk.CodeRules.Api.Controllers;
using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("Records")]
    [TestClass]
    public class RJIT_CR_R_00005 : ControllerTestBase
    {
        [TestMethod]
        public void Records_Should_Never_Be_Partial()
        {
            var recordWithPartialModifiers = (from syntaxTree in SyntaxTreesToAnalyze
                                            from record in syntaxTree.Records
                                            from modifiers in record.Modifiers
                                            where modifiers == Modifier.Partial
                                            select new
                                            {
                                                Error = $@"
Do not use partial record in production code ! If you have regex code inside then you have logic in your code.
Records are just pure data containers !
----------------------------------------------------------------------------------------------------------------------------
FullName:   {record.FullQualifiedName}
----------------------------------------------------------------------------------------------------------------------------
Record:     

{@record.SyntaxTree.FormatSyntaxTree()}
----------------------------------------------------------------------------------------------------------------------------
Should be:    

{@record.Normalize()}
----------------------------------------------------------------------------------------------------------------------------
"
                                            }).ToImmutableList();

            Assert.IsTrue(recordWithPartialModifiers.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_R_00005

Records should never be partial. Findings: '{recordWithPartialModifiers.Count}':{Environment.NewLine}{recordWithPartialModifiers.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }
}
